export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tApex = u / g;
  const tDuration = (2 * u) / g;
  const tClamped = Math.max(0, Math.min(time, tDuration));

  const v = u - g * tClamped;
  const a = -g;
  const F = m * g;
  const y = u * tClamped - 0.5 * g * tClamped * tClamped;

  let stateLabel = "Ready to toss";
  if (tClamped > 0 && Math.abs(tClamped - tApex) > 0.02) {
    if (tClamped < tApex) stateLabel = "Rising";
    else stateLabel = "Falling";
  } else if (tClamped > 0 && Math.abs(tClamped - tApex) <= 0.02) {
    stateLabel = "At the top";
  } else if (tClamped >= tDuration - 1e-4) {
    stateLabel = "Back at launch height";
  }

  const leftLane = sdk.panel({
    x: 20,
    y: 35,
    w: 280,
    h: 365,
    title: "The motion",
    state: stateLabel,
    id: "lane.left"
  });

  const leftAxis = sdk.axis("axis.y", {
    x: 80,
    y: 370,
    length: 290,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height y",
    unit: "m"
  });

  const ballPixelY = 370 - (y / 2.2) * 290;
  const ballPixelX = 130;

  const ball = sdk.circle("ball.toss", ballPixelX, ballPixelY, 26);

  const vScale = 18;
  const vecV = sdk.vector(
    "vec.v",
    { x: ballPixelX,
      y: ballPixelY },
    {
      value: v,
      direction: "up",
      scale: vScale,
      label: `v = ${sdk.format(v, 2)} m/s`,
      role: "output"
    }
  );

  const vecA = sdk.vector(
    "vec.a",
    { x: ballPixelX + 45,
      y: ballPixelY },
    {
      value: a,
      direction: "up",
      scale: 12,
      label: `a = ${sdk.format(a, 1)} m/s²`,
      role: "warning"
    }
  );

  const calloutLines = [
    `v: ${sdk.format(v, 2)} m/s`,
    `a: ${sdk.format(a, 1)} m/s²`,
    `Fg: ${sdk.format(F, 1)} N`
  ];
  const callout = sdk.callout(ballPixelX - 90, ballPixelY - 20, calloutLines, {
    id: "callout.toss"
  });

  const rightLane = sdk.panel({
    x: 320,
    y: 35,
    w: 300,
    h: 365,
    title: "Velocity over time",
    state: `t = ${sdk.format(tClamped, 2)} s`,
    id: "lane.right"
  });

  const numPoints = 24;
  const points = [];
  for (let i = 0; i <= numPoints; i++) {
    const tSample = (1.8 * i) / numPoints;
    const vSample = u - g * tSample;
    points.push({ x: tSample, y: vSample });
  }

  const vtPlot = sdk.plot("plot.vt", {
    x: 335,
    y: 70,
    w: 270,
    h: 310,
    axes: {
      x: { label: "Time t", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity v", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      {
        label: "v(t)",
        kind: "line",
        points: points
      }
    ]
  });

  const objects = [
    ...leftLane,
    leftAxis,
    ball,
    ...vecV,
    ...vecA,
    ...callout,
    ...rightLane,
    vtPlot
  ];

  const quantities = {
    launchSpeed: u,
    gravity: g,
    mass: m,
    apexTime: tApex,
    apexHeight: (u * u) / (2 * g),
    height: y,
    velocity: v,
    acceleration: a,
    force: F
  };

  const readouts = [
    { id: "velocity", value: v },
    { id: "acceleration", value: a },
    { id: "force", value: F },
    { id: "motionState", value: stateLabel }
  ];

  return { frame: { width: 640, height: 420, objects, readouts }, quantities };
}
